@RestController
@RequestMapping("/members")
public class MemberController {

    private final RegisterMemberUseCase registerMemberUseCase;
    private final GetMemberUseCase getMemberUseCase;
    private final ListActiveLoansUseCase listActiveLoansUseCase;

    public MemberController(RegisterMemberUseCase registerMemberUseCase, GetMemberUseCase getMemberUseCase,
                            ListActiveLoansUseCase listActiveLoansUseCase) {
        this.registerMemberUseCase = registerMemberUseCase;
        this.getMemberUseCase = getMemberUseCase;
        this.listActiveLoansUseCase = listActiveLoansUseCase;
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public MemberResponse registerMember(@RequestBody RegisterMemberRequest request) {
        Member member = registerMemberUseCase.registerMember(new RegisterMemberCommand(request.name()));
        return MemberResponse.from(member);
    }

    @GetMapping("/{memberId}")
    public MemberResponse getMember(@PathVariable UUID memberId) {
        return MemberResponse.from(getMemberUseCase.getMember(memberId));
    }

    @GetMapping("/{memberId}/loans")
    public ActiveLoanPageResponse listActiveLoans(@PathVariable UUID memberId,
                                                  @RequestParam(defaultValue = "0") int page,
                                                  @RequestParam(defaultValue = "20") int size) {
        return ActiveLoanPageResponse.from(
                listActiveLoansUseCase.listActiveLoans(new ListActiveLoansQuery(memberId, page, size)));
    }
}
package com.example.lending;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.ResultActions;

import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class MemberActiveLoanIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void active_loans_are_listed_with_title_and_due_date_and_total_count() throws Exception {
        String memberId = registerMember();
        String bookId = registerBook("Clean Code");
        loanBook(bookId, memberId, "2026-02-02");

        mockMvc.perform(get("/members/{memberId}/loans", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.items.length()").value(1))
                .andExpect(jsonPath("$.items[0].bookId").value(bookId))
                .andExpect(jsonPath("$.items[0].title").value("Clean Code"))
                .andExpect(jsonPath("$.items[0].loanedAt").value("2026-02-02"))
                .andExpect(jsonPath("$.items[0].dueAt").value("2026-02-16"))
                .andExpect(jsonPath("$.items[0].loanId").isNotEmpty())
                .andExpect(jsonPath("$.page").value(0))
                .andExpect(jsonPath("$.size").value(20))
                .andExpect(jsonPath("$.totalCount").value(1));
    }

    @Test
    void returned_loans_are_excluded() throws Exception {
        String memberId = registerMember();
        String returnedLoanId = loanBook(registerBook("Returned Book"), memberId, "2026-02-02");
        loanBook(registerBook("Still Out"), memberId, "2026-02-03");

        mockMvc.perform(post("/loans/{loanId}/return", returnedLoanId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"returnedAt\":\"2026-02-05\"}"))
                .andExpect(status().isOk());

        mockMvc.perform(get("/members/{memberId}/loans", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.items.length()").value(1))
                .andExpect(jsonPath("$.items[0].title").value("Still Out"))
                .andExpect(jsonPath("$.totalCount").value(1));
    }

    @Test
    void pages_are_sliced_and_total_count_ignores_page() throws Exception {
        String memberId = registerMember();
        loanBook(registerBook("First"), memberId, "2026-02-01");
        loanBook(registerBook("Second"), memberId, "2026-02-02");
        loanBook(registerBook("Third"), memberId, "2026-02-03");

        mockMvc.perform(get("/members/{memberId}/loans", memberId).param("page", "0").param("size", "2"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.items.length()").value(2))
                .andExpect(jsonPath("$.items[0].title").value("First"))
                .andExpect(jsonPath("$.items[1].title").value("Second"))
                .andExpect(jsonPath("$.page").value(0))
                .andExpect(jsonPath("$.size").value(2))
