package com.example.lending.application.service;

import com.example.lending.application.port.in.ListActiveLoansUseCase;
import com.example.lending.application.port.out.LoadBookPort;
import com.example.lending.application.port.out.LoadLoanPort;
import com.example.lending.application.port.out.LoadMemberPort;
import com.example.lending.domain.Book;
import com.example.lending.domain.BookNotFoundException;
import com.example.lending.domain.Loan;
import com.example.lending.domain.MemberNotFoundException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.function.Function;
import java.util.stream.Collectors;

@Service
@Transactional(readOnly = true)
public class ListActiveLoansService implements ListActiveLoansUseCase {

    private final LoadMemberPort loadMemberPort;
    private final LoadLoanPort loadLoanPort;
    private final LoadBookPort loadBookPort;

    public ListActiveLoansService(LoadMemberPort loadMemberPort, LoadLoanPort loadLoanPort, LoadBookPort loadBookPort) {
        this.loadMemberPort = loadMemberPort;
        this.loadLoanPort = loadLoanPort;
        this.loadBookPort = loadBookPort;
    }

    @Override
    public ActiveLoanPage listActiveLoans(ListActiveLoansQuery query) {
        UUID memberId = query.memberId();
        loadMemberPort.loadMember(memberId).orElseThrow(() -> new MemberNotFoundException(memberId));

        long totalCount = loadLoanPort.countActiveLoansByMemberId(memberId);
        List<Loan> loans = loadLoanPort.loadActiveLoansByMemberId(memberId, query.page(), query.size());
        Map<UUID, String> titles = titlesByBookId(loans);

        List<ActiveLoan> items = loans.stream()
                .map(loan -> new ActiveLoan(loan.getId(), loan.getBookId(), titles.get(loan.getBookId()),
                        loan.getLoanedAt(), loan.getDueAt()))
                .toList();
        return new ActiveLoanPage(items, query.page(), query.size(), totalCount);
    }

    private Map<UUID, String> titlesByBookId(List<Loan> loans) {
        List<UUID> bookIds = loans.stream().map(Loan::getBookId).distinct().toList();
        Map<UUID, Book> booksById = loadBookPort.loadBooks(bookIds).stream()
                .collect(Collectors.toMap(Book::getId, Function.identity()));
        return bookIds.stream().collect(Collectors.toMap(Function.identity(), bookId -> {
            Book book = booksById.get(bookId);
            if (book == null) {
                throw new BookNotFoundException(bookId);
            }
            return book.getTitle();
        }));
    }
}
package com.example.lending.adapter.out.persistence;

import com.example.lending.application.port.out.LoadLoanPort;
import com.example.lending.application.port.out.SaveLoanPort;
import com.example.lending.domain.Loan;
import org.springframework.data.domain.PageRequest;
import org.springframework.data.domain.Pageable;
import org.springframework.data.domain.Sort;
import org.springframework.stereotype.Component;

import java.util.List;
import java.util.Optional;
import java.util.UUID;

@Component
public class LoanPersistenceAdapter implements LoadLoanPort, SaveLoanPort {

    private final LoanJpaRepository loanJpaRepository;
    private final LoanMapper loanMapper = new LoanMapper();

    public LoanPersistenceAdapter(LoanJpaRepository loanJpaRepository) {
        this.loanJpaRepository = loanJpaRepository;
    }

    @Override
    public Optional<Loan> loadLoan(UUID loanId) {
        return loanJpaRepository.findById(loanId).map(loanMapper::toDomain);
    }

    @Override
    public long countActiveLoansByMemberId(UUID memberId) {
        return loanJpaRepository.countByMemberIdAndReturnedAtIsNull(memberId);
    }

    @Override
    public List<Loan> loadActiveLoansByMemberId(UUID memberId, int page, int size) {
        Pageable pageable = PageRequest.of(page, size, Sort.by("loanedAt", "id"));
        return loanJpaRepository.findByMemberIdAndReturnedAtIsNull(memberId, pageable).stream()
                .map(loanMapper::toDomain)
                .toList();
    }

    @Override
    public void saveLoan(Loan loan) {
        loanJpaRepository.save(loanMapper.toEntity(loan));
    }
}
