package com.example.lending;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.ResultActions;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class BookSearchIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void books_whose_title_contains_the_keyword_are_returned() throws Exception {
        String bookId = registerBook("Spring in Action");
        registerBook("Clean Code");

        mockMvc.perform(get("/books").param("title", "Spring"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(1))
                .andExpect(jsonPath("$[0].id").value(bookId))
                .andExpect(jsonPath("$[0].title").value("Spring in Action"))
                .andExpect(jsonPath("$[0].status").value("AVAILABLE"));
    }

    @Test
    void keyword_match_ignores_case() throws Exception {
        registerBook("Spring in Action");

        mockMvc.perform(get("/books").param("title", "sPRING"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(1))
                .andExpect(jsonPath("$[0].title").value("Spring in Action"));
    }

    @Test
    void keyword_matches_a_part_of_the_title_anywhere() throws Exception {
        registerBook("Effective Java");
        registerBook("Java Concurrency in Practice");
        registerBook("Clean Code");

        mockMvc.perform(get("/books").param("title", "va"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(2))
                .andExpect(jsonPath("$[0].title").value("Effective Java"))
                .andExpect(jsonPath("$[1].title").value("Java Concurrency in Practice"));
    }

    @Test
    void wildcard_characters_in_keyword_are_matched_literally() throws Exception {
        registerBook("100% Java");
        registerBook("Java Basics");

        mockMvc.perform(get("/books").param("title", "100%"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(1))
                .andExpect(jsonPath("$[0].title").value("100% Java"));
    }

    @Test
    void no_matching_book_returns_empty_list() throws Exception {
        registerBook("Clean Code");

        mockMvc.perform(get("/books").param("title", "Spring"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(0));
    }

    @Test
    void blank_or_missing_title_returns_400() throws Exception {
        mockMvc.perform(get("/books").param("title", " "))
                .andExpect(status().isBadRequest());
        mockMvc.perform(get("/books"))
                .andExpect(status().isBadRequest());
    }

    private String registerBook(String title) throws Exception {
        return readId(mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"" + title + "\"}")), "id");
    }

    private String readId(ResultActions result, String field) throws Exception {
        String body = result.andReturn().getResponse().getContentAsString();
        JsonNode node = objectMapper.readTree(body);
        return node.get(field).asText();
    }
}
